mapper.select:
SELECT id, create_user_name AS createUserName, create_time AS createTime, update_user_id AS updateUserId , update_user_name AS updateUserName, update_time AS updateTime, version, is_deleted, name, type, company_name AS companyName , contact, email, tel_number AS telNumber, country, country_name AS countryName, province_name AS provinceName, city_name AS cityName, district_name AS districtName, address_first AS addressFirst, address_second AS addressSecond, zip_code AS zipCode FROM logistics_address la WHERE ${params.sqlMap.default} and la.is_deleted=FALSE
AND la.type IN
#{item}
AND ( la.address_first ILIKE concat('%',#{params.address}::text,'%') OR la.address_second ILIKE concat('%',#{params.address}::text,'%') )
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
la.create_time DESC

